 * Parses a limiter file into declared policies, routes and events, or throws
 * an `Error` whose message is `line N: <reason>` describing the first
 * malformed line.
 */

const NAME_RE = /^[A-Za-z0-9_.\/:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

function checkIntField(str, field, min) {
  if (!INT_RE.test(str)) {
    throw new Error(`${field} must be an integer of at least ${min}`)
  }
  const value = BigInt(str)
  if (value < min) {
    throw new Error(`${field} must be an integer of at least ${min}`)
  }
  return value
}

export function parseProgram(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const policies = new Map()
  const routes = new Map()
  const events = []
  let seenEvent = false
  let lastTick = null

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const tokens = line.split(/\s+/)
    const dir = tokens[0]

    try {
      if (dir === 'bucket') {
        if (seenEvent) throw new Error('declarations must come before the first event')
        if (tokens.length !== 5) throw new Error('expected bucket <name> <capacity> <refill> <per>')
        const [, name, capS, refillS, perS] = tokens
        if (!NAME_RE.test(name)) throw new Error(`invalid policy name ${name}`)
        if (policies.has(name)) throw new Error(`policy ${name} is declared twice`)
        const capacity = checkIntField(capS, 'capacity', 1n)
        const refill = checkIntField(refillS, 'refill', 0n)
        const per = checkIntField(perS, 'per', 1n)
        policies.set(name, { type: 'bucket', capacity, refill, per, state: new Map() })
      } else if (dir === 'window') {
        if (seenEvent) throw new Error('declarations must come before the first event')
        if (tokens.length !== 4) throw new Error('expected window <name> <limit> <span>')
        const [, name, limitS, spanS] = tokens
        if (!NAME_RE.test(name)) throw new Error(`invalid policy name ${name}`)
        if (policies.has(name)) throw new Error(`policy ${name} is declared twice`)
        const limit = checkIntField(limitS, 'limit', 0n)
        const span = checkIntField(spanS, 'span', 1n)
        policies.set(name, { type: 'window', limit, span, state: new Map() })
      } else if (dir === 'route') {
        if (seenEvent) throw new Error('declarations must come before the first event')
        if (tokens.length < 3) throw new Error('expected route <prefix> <policy>...')
        const prefix = tokens[1]
        if (!NAME_RE.test(prefix)) throw new Error(`invalid route prefix ${prefix}`)
        if (routes.has(prefix)) throw new Error(`prefix ${prefix} is routed twice`)
        const policyNames = tokens.slice(2)
        for (const name of policyNames) {
          if (!policies.has(name)) throw new Error(`unknown policy ${name}`)
        }
        routes.set(prefix, policyNames)
      } else if (dir === 'event') {
        if (tokens.length !== 3) throw new Error('expected event <tick> <key>')
        const [, tickS, key] = tokens
        const tick = checkIntField(tickS, 'tick', 0n)
        if (!NAME_RE.test(key)) throw new Error(`invalid key ${key}`)
        if (lastTick !== null && tick < lastTick) {
          throw new Error(`tick ${tick} is before tick ${lastTick}`)
        }
        lastTick = tick
        seenEvent = true
        events.push({ tick, key })
      } else {
        throw new Error(`unknown directive ${dir}`)
      }
    } catch (err) {
      throw new Error(`line ${lineNo}: ${err.message}`)
    }
  }

  return { policies, routes, events }
}
"}

