 * Per-key state machines for the two policy kinds. Each keeps one
 * independent state per key, advanced to an event's tick before the event
 * is checked and, if allowed, recorded.
 */

/**
 * A token bucket. Tokens are tracked as an exact multiple of `1/per` (via a
 * BigInt numerator over the fixed denominator `per`) so that partial-period
 * refills never lose precision to rounding.
 */
export class Bucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.state = new Map()
  }

  advance(key, tick) {
    let s = this.state.get(key)
    if (!s) {
      s = { numerator: this.capacity * this.per, lastTick: tick }
      this.state.set(key, s)
      return
    }
    const elapsed = tick - s.lastTick
    if (elapsed > 0n) {
      const cap = this.capacity * this.per
      s.numerator += this.refill * elapsed
      if (s.numerator > cap) s.numerator = cap
      s.lastTick = tick
    }
  }

  allow(key) {
    return this.state.get(key).numerator >= this.per
  }

  commit(key) {
    this.state.get(key).numerator -= this.per
  }
}

/** A sliding window remembering the ticks of the requests it recorded. */
export class Window {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.state = new Map()
  }

  advance(key, tick) {
    let s = this.state.get(key)
    if (!s) {
      s = []
      this.state.set(key, s)
    }
    const threshold = tick - this.span
    while (s.length > 0 && s[0] <= threshold) s.shift()
  }

  allow(key) {
    return BigInt(this.state.get(key).length) < this.limit
  }

  commit(key, tick) {
    this.state.get(key).push(tick)
  }
}

export function buildPolicy(decl) {
  if (decl.type === 'bucket') return new Bucket(decl.capacity, decl.refill, decl.per)
  return new Window(decl.limit, decl.span)
}
"}

