/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { readFileSync } from 'node:fs'
import { parseProgram } from './parser.js'
import { replay } from './engine.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'replay' && mode !== 'summary')) {
    fail('usage: cli.js replay|summary')
  }

  const input = readFileSync(0, 'utf8')

  let program
  try {
    program = parseProgram(input)
  } catch (err) {
    fail(err.message)
    return
  }

  const results = replay(program)

  let out
  if (mode === 'replay') {
    out = results
      .map((r) => (r.allow ? `${r.tick} ${r.key} allow` : `${r.tick} ${r.key} deny ${r.denyPolicy}`))
      .join('\n')
    if (out.length > 0) out += '\n'
  } else {
    const totals = new Map()
    for (const r of results) {
      let t = totals.get(r.key)
      if (!t) {
        t = { allowed: 0n, denied: 0n }
        totals.set(r.key, t)
      }
      if (r.allow) t.allowed += 1n
      else t.denied += 1n
    }
    const keys = [...totals.keys()].sort()
    let allAllowed = 0n
    let allDenied = 0n
    const lines = []
    for (const key of keys) {
      const t = totals.get(key)
      allAllowed += t.allowed
      allDenied += t.denied
      lines.push(`${key} allowed=${t.allowed} denied=${t.denied}`)
    }
    lines.push(`total allowed=${allAllowed} denied=${allDenied}`)
    out = lines.join('\n') + '\n'
  }

  process.stdout.write(out)
}

main()
"}

